        result = 1
        for num in range(1, x + 1):
            result *= num
        return result

    result = []
    for idx in range(n):
        i = idx + 1
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(i * (i + 1) // 2)
    return result

